WITH base AS (SELECT *, LAST_DAY(hire_date) hire_date_month_end, DATE_SUB(hire_date, 23) hire_date_minus_23d FROM employees WHERE email LIKE '%@gmail.com') SELECT CASE WHEN salary >= 158000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, COUNT_IF(job_title = 'Intern') AS intern_events, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT level) AS distinct_levels, SUM(CASE WHEN job_title = 'Designer' THEN salary ELSE 0 END) AS designer_salary FROM base GROUP BY salary_tier
